 if(S.original){clearComparison();render();return;}
 if(S.view!=='map'||!S.layout||S.stroke)return;
 const files=S.files,id=S.layout.id,layout=JSON.parse(C.strFromU8(S.base.get('data/layouts/layouts.json'))).layouts.find(l=>l.id===id);
