function paint(x,y){if(S.view==='map'){if(x<0||y<0||x>=S.layout.width||y>=S.layout.height)return;const i=y*S.layout.width+x;if(S.tool==='pick'){studio.chooseTile(S.cells[i]&1023);$('collisionValue').value=S.cells[i]>>>10&3;$('elevationValue').value=S.cells[i]>>>12;inspectCell(x,y);paletteUI();return;}const collision=$('paintCollision').checked?+$('collisionValue').value:null,elev=$('paintElevation').checked?+$('elevationValue').value:null,tile=$('paintCollision').checked||$('paintElevation').checked?null:S.selected,value=C.paintBlock(S.cells[i],tile,collision,elev);if(S.tool==='fill'){const mask=(collision!=null?0x0c00:0)|(elev!=null?0xf000:0)||0x03ff;C.fillFields(S.cells,S.layout.width,S.layout.height,x,y,value,mask);}else {if(S.cells[i]===value)return;S.cells[i]=value;}}else if(S.view==='tiles'&&S.sheet){const p=S.sheet.png;if(x<0||y<0||x>=p.w||y>=p.h)return;if(S.tool==='pick'){S.color=p.pixels[y*p.w+x];paletteUI();return;}p.pixels[y*p.w+x]=S.color;}else if(S.view==='rom'&&S.romPixels&&!S.romPreview){const tile=Math.floor(y/8)*16+Math.floor(x/8),i=tile*64+y%8*8+x%8;if(x<0||y<0||x>=128||i>=S.romPixels.length)return;if(S.tool==='pick'){S.color=S.romPixels[i];paletteUI();return;}S.romPixels[i]=S.color;}inspectCell(x,y);render();}
$('canvas').addEventListener('pointerdown',e=>{if(S.busy||S.stroke)return;if(!S.original&&mapTools.pointerDown(e,eventPos(e)))return;if(!S.original&&e.pointerType!=='touch'&&studio.pointerDown(e,eventPos(e)))return;e.preventDefault();$('canvas').setPointerCapture(e.pointerId);const p=eventPos(e),pan=S.original||S.tool==='pan'||e.pointerType==='touch'&&$('eventsPanel').open;let before,path;if(!pan){if(S.view==='map'&&S.cells){path=S.layout.blockdata_filepath;before=S.files.get(path).slice();}else if(S.view==='tiles'&&S.sheet){path=S.sheet.image;before=S.files.get(path).slice();}else if(S.view==='rom'&&S.rom&&!S.romPreview&&S.romPixels){path='@rom';before=S.rom.slice();}else return;}S.stroke={pointer:e.pointerId,pointerType:e.pointerType,last:p,path,before,pan,sx:e.clientX,sy:e.clientY,left:$('canvasWrap').scrollLeft,top:$('canvasWrap').scrollTop};if(!pan&&!(S.tool==='pick'&&e.pointerType==='touch'))paint(p.x,p.y);});
$('canvas').addEventListener('pointermove',e=>{const p=eventPos(e);$('cursorPosition').textContent='X '+p.x+' · Y '+p.y;inspectCell(p.x,p.y);if(!S.original)mapTools.pointerMove(e,p);const s=S.stroke;if(!s||s.pointer!==e.pointerId)return;if(s.pan){s.distance=Math.max(s.distance||0,Math.hypot(e.clientX-s.sx,e.clientY-s.sy));$('canvasWrap').scrollLeft=s.left+s.sx-e.clientX;$('canvasWrap').scrollTop=s.top+s.sy-e.clientY;return;}if(S.tool==='pencil')C.line(s.last.x,s.last.y,p.x,p.y,paint);s.last=p;});
