async function refresh(){if(S.rom){romTools.invalidate();if(S.romPixels&&!S.romPreview)S.romPixels=C.read4bpp(S.rom,S.romOffset,S.romPixels.length/64);readHex();render();}else if(S.layout){const id=S.layout.id,sheet=S.sheet?.symbol,palette=$('paletteSelect').value;S.layouts=JSON.parse(txt('data/layouts/layouts.json')).layouts;await selectLayout(S.layouts.find(l=>l.id===id)||S.layouts[0],{keepView:true});if(S.view==='tiles'){S.sheet=S.sets.find(s=>s.symbol===sheet)||S.sets[0];$('sheetSelect').value=S.sets.indexOf(S.sheet);$('paletteSelect').value=palette;$('sheetSelect').dispatchEvent(new Event('change'));$('paletteSelect').dispatchEvent(new Event('change'));paletteUI();render();}}updateChanges();}
async function undo(redo=false){const from=redo?S.redo:S.history,to=redo?S.history:S.redo,entry=from.pop();if(!entry)return;to.push(entry);for(const change of entry.changes||[entry]){const bytes=(redo?change.after:change.before)?.slice();if(change.path==='@rom')S.rom.set(bytes,change.offset);else if(bytes)S.files.set(change.path,bytes);else S.files.delete(change.path);}await refresh();queueDraft();status((redo?'Redid':'Undid')+' edit · '+(entry.path||entry.changes.map(c=>c.path).join(', ')));}
function dirtyCount(){return S.rom?Number(!C.equal(S.rom,S.romBase)):C.changedFiles(S.base,S.files).length;}
function updateChanges(){const n=dirtyCount();$('changeCount').textContent=n;$('exportBtn').setAttribute('aria-label','Export · '+n+' changed files');$('undoBtn').disabled=!S.history.length;$('redoBtn').disabled=!S.redo.length;$('undoCount').textContent=S.history.length;$('undoCount').hidden=!S.history.length;$('saveState').textContent=n?n+(S.rom?' modified ROM':' changed file'+(n===1?'':'s')):'Local workspace';}
function download(name,bytes,mime='application/octet-stream'){if(window.AndroidFiles){window.AndroidFiles.beginSave(name,mime);const size=49152;for(let i=0;i<bytes.length;i+=size){let str='';for(const x of bytes.subarray(i,i+size))str+=String.fromCharCode(x);window.AndroidFiles.appendSave(btoa(str));}window.AndroidFiles.finishSave();return;}const a=$('downloadLink');if(a.dataset.url)URL.revokeObjectURL(a.dataset.url);const u=URL.createObjectURL(new Blob([bytes],{type:mime}));a.href=u;a.download=name;a.dataset.url=u;$('downloadName').textContent=name+' · '+(bytes.length<1024?bytes.length+' B':(bytes.length/1024).toFixed(1)+' KB');$('downloadDialog').showModal();}
async function exportEdits(){if(S.rom){download((S.romName||'game').replace(/\.gba$/i,'')+'-tileforge.gba',S.rom);toast('Edited ROM copy exported.');return;}await studio.beforeExport();const changed=C.changedFiles(S.base,S.files);if(!changed.length){toast('Make an edit first, or save the full project.');return;}const manifest={format:'tileforge-changes',formatVersion:1,editorVersion:C.VERSION,createdAt:new Date().toISOString(),source:S.source,files:await Promise.all(changed.map(async([path,b])=>({path,size:b.length,originalSha256:S.base.has(path)?await C.sha256(S.base.get(path)):null,sha256:await C.sha256(b)})))};const files=Object.fromEntries(changed);files['tileforge-changes.json']=C.strToU8(JSON.stringify(manifest,null,2));files['READ-ME.txt']=C.strToU8('TileForge Studio edits\n\nUpload this ZIP to chat for integration. Source paths are relative to the project root. Check each originalSha256 before replacing a file; mismatches mean the source changed since editing. Never overwrite mismatches. Use tools/apply_changes.py for a dry run and conflict-checked application. Shared tilesets affect all maps using them. Compile the source project to produce a new ROM.\n');download('TileForge-'+(S.source.version||'project')+'-edits.zip',C.zipSync(files,{level:6}),'application/zip');$('exportDialog').close();toast(changed.length+' changed files packaged. Save the ZIP to share it.');}
function toBase64(b){let s='';for(let i=0;i<b.length;i+=8192)s+=String.fromCharCode(...b.subarray(i,i+8192));return btoa(s);}
function fromBase64(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0));}
function fullExport(){if(S.rom){download((S.romName||'game').replace(/\.gba$/i,'')+'-tileforge.gba',S.rom);return;}const baseline={};for(const[p]of C.changedFiles(S.base,S.files))if(S.base.has(p))baseline[p]=toBase64(S.base.get(p));const createdPaths=[...S.files.keys()].filter(p=>!S.base.has(p));const project={createdPaths,format:'tileforge-project',formatVersion:1,source:S.source,selectedLayout:S.layout?.id,studio:studio.serialize(),areas:mapTools.serialize(),baseline};const files=Object.fromEntries(S.files);files['tileforge-project.json']=C.strToU8(JSON.stringify(project));download('TileForge-'+(S.source.version||'source')+'-project.zip',C.zipSync(files,{level:6}),'application/zip');toast('Editable project exported. It includes all currently loaded maps.');}
function showExport(){if(!workflow.ready)return;workflow.exportStage();const list=$('exportFileList');list.replaceChildren();for(const [path,bytes]of(S.rom?[[S.romName||'game.gba',S.rom]]:C.changedFiles(S.base,S.files))){const li=document.createElement('li');li.textContent=path+' · '+(bytes.length<1024?bytes.length+' B':(bytes.length/1024).toFixed(1)+' KB');list.append(li);}$('exportFiles').hidden=!list.children.length;const n=dirtyCount();$('exportSummary').textContent=S.rom?(n?'Your modified ROM is ready to export as a new .GBA file.':'No ROM changes yet. You can still export a copy.'):n+' source file'+(n===1?'':'s')+' changed. '+(S.layout?.name||'')+'. '+(S.source.revision?'Based on '+S.source.revision.slice(0,8)+'.':'');$('exportActionTitle').textContent=S.rom?'Export edited .GBA':'Share edits ZIP';$('exportActionDescription').textContent=S.rom?'Save a new ROM copy with your applied edits.':'Only changed source files, ready to upload back to chat.';$('sourceExportFlow').hidden=!!S.rom;$('exportNote').textContent=S.rom?'This saves a separate .GBA copy. Your original ROM file stays unchanged.':'Shared tilesets affect every map that uses them. The manifest records exactly which files changed.';$('fullExport').hidden=!!S.rom;$('exportReviewEvents').hidden=!!S.rom;$('exportDialog').showModal();}
async function openFile(file){if(!confirmReplace())return;clearTimeout(saveTimer);S.draftId=null;if(file.size>350*1024*1024)throw Error('File too large. Use a smaller source pack.');const b=new Uint8Array(await file.arrayBuffer());if(/\.gba$/i.test(file.name)){const info=C.romInfo(b);S.rom=b;S.romBase=b.slice();S.romName=file.name;S.source={type:'rom',name:file.name};tool('pan');S.history=[];S.redo=[];S.romPixels=null;S.romPreview=false;romTools.reset();$('projectName').textContent=file.name;$('modeLabel').textContent='GBA';$('romInfo').textContent=info.title+' · '+info.code+' · '+(info.size/1048576).toFixed(2)+' MB. Map decoding is not available from ROMs in this alpha; use source for Legends maps.';view('rom');updateChanges();readHex();workflow.enter(true);queueDraft();status('ROM opened locally. Use a known graphics offset or the hex editor.');return;}const f=C.sourceZip(b),meta=f.has('tileforge-project.json')?JSON.parse(decoder.decode(f.get('tileforge-project.json'))):null;reset(f,meta?.source||{type:'zip',name:file.name});studio.reset(meta?.studio);mapTools.reset(meta?.areas);for(const p of meta?.createdPaths||[]){C.safePath(p);S.base.delete(p);}if(meta?.baseline)for(const[p,v]of Object.entries(meta.baseline)){C.safePath(p);S.base.set(p,fromBase64(v));}await selectLayout(defaultLayout(S.layouts,meta?.selectedLayout));view('map');workflow.enter(true);queueDraft();toast('Source project opened.');}
function parseOffset(id){const s=$(id).value.trim().replace(/^0x/i,'');if(!/^[\da-fA-F]{1,8}$/.test(s))throw Error('Enter a valid hexadecimal offset');return parseInt(s,16);}
function loadRomGraphics(compressed=false){if(!S.rom)throw Error('Open a .GBA file first');const offset=parseOffset('romOffset'),count=Number($('romTileCount').value);if(!Number.isInteger(count)||count<1||count>1024)throw Error('Choose 1–1024 tiles');let bytes=S.rom,base=offset;if(compressed){bytes=C.lz77(S.rom,offset).bytes;base=0;if(bytes.length%32)throw Error('Decompressed size is not 4bpp tile data');S.romPixels=C.read4bpp(bytes,0,Math.min(bytes.length/32,1024));}else S.romPixels=C.read4bpp(bytes,base,count);S.romOffset=offset;S.romPreview=compressed;render();fit();status(compressed?'LZ77 graphics preview · read-only':'Uncompressed graphics · changes write to a new ROM copy');}
