function queueDraft(){if(!workflow.ready||!S.layout&&!S.rom)return;clearTimeout(saveTimer);workflow.saving();saveTimer=setTimeout(()=>saveDraft().catch(e=>{workflow.failed();$('saveState').textContent=e.code==='DRAFT_LIMIT'?'10 drafts · free a slot or export':'Draft unavailable · export to save';if(e.code==='DRAFT_LIMIT'){$('draftLimitNotice').hidden=false;$('draftLimitNotice').textContent=e.message;$('draftSlotNotice').hidden=false;$('draftLabel').textContent='10 drafts full';}}),700);}
async function saveDraft(){if(!workflow.ready)throw Error('Load a project first');clearTimeout(saveTimer);workflow.saving();const key=S.draftId||(S.draftId='draft-'+(crypto.randomUUID?.()||Date.now()+'-'+Math.random().toString(16).slice(2))),sequence=(S.draftSequence||0)+1;S.draftSequence=sequence;const savedAt=Date.now(),common={format:'tileforge-draft',formatVersion:2,savedAt,name:S.rom?S.romName:S.source.name,kind:S.rom?'rom':'source',changes:dirtyCount(),source:S.source,history:S.history,redo:S.redo,view:S.view,selected:S.selected,color:S.color};const snapshot=structuredClone(S.rom?{...common,rom:S.rom,romBase:S.romBase,romName:S.romName,romPixels:S.romPixels,romOffset:S.romOffset,romPreview:S.romPreview,romTools:romTools.serialize()}:{...common,files:[...S.files],base:[...S.base],layout:S.layout?.id,studio:studio.serialize(),areas:mapTools.serialize()});const operation=draftWrite.catch(()=>{}).then(()=>Drafts.putDraft(key,snapshot));draftWrite=operation;try{await operation;if(S.draftId===key&&S.draftSequence===sequence){workflow.saved(savedAt);$('draftLimitNotice').hidden=true;$('draftSlotNotice').hidden=true;$('saveState').textContent='Draft saved on device';}await readDraft();}catch(e){workflow.failed();if(e.code==='DRAFT_LIMIT'){$('draftLimitNotice').hidden=false;$('draftLimitNotice').textContent=e.message;$('draftSlotNotice').hidden=false;$('draftLabel').textContent='10 drafts full';throw e;}throw Error('Draft could not be saved. Export an editable project to keep your work.');}}
