 const operation=draftWrite.catch(()=>{}).then(()=>Drafts.deleteDraft(key));draftWrite=operation;await operation;await readDraft();toast('Draft moved to Deleted drafts. Open files are retained; your next edit or Save draft creates a new draft.');
